INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Cyberangriffe immer auf finanziellen Gewinn aus?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Spionage oder Sabotage möglich"}, {"text": "Ja", "correct": false, "because": "Motive variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen die meisten Angriffe auf Unternehmen?', 3, '[{"text": "Datendiebstahl", "correct": true, "because": "Häufigster Zweck"}, {"text": "Hardware-Schaden", "correct": false, "because": "Seltener"}, {"text": "Bandbreitenerhöhung", "correct": false, "because": "Kein Angriffsziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutzen Cyberangriffe häufig?', 5, '[{"text": "Phishing", "correct": true, "because": "Täuscht Nutzer"}, {"text": "Ransomware", "correct": true, "because": "Erpresst Opfer"}, {"text": "Grafikmanipulation", "correct": false, "because": "Kein Angriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cyberangriffe nutzen oft KI. b) Sie sind immer staatlich gefördert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Staatlich nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Abwehr von Angriffen?', 4, '[{"text": "Mitarbeiterschulung", "correct": false, "because": "Reduziert Risiken"}, {"text": "Updates", "correct": false, "because": "Schließt Lücken"}, {"text": "Bildschirmdesign", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob alle Cyberangriffe Malware nutzen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Phishing ohne Malware"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik stoppt Angriffe effektiv?', 3, '[{"text": "MFA", "correct": true, "because": "Zweiter Faktor schützt"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Kein Schutz"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Zu langsam"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branchen sind oft betroffen?', 5, '[{"text": "Finanzwesen", "correct": true, "because": "Hoher Wert"}, {"text": "Gesundheitswesen", "correct": true, "because": "Sensible Daten"}, {"text": "Gaming", "correct": false, "because": "Weniger primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Angriffe nehmen zu. b) Sie sind immer erkennbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erkennung schwierig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht zur Abwehr?', 4, '[{"text": "Firewall", "correct": false, "because": "Schützt Netzwerk"}, {"text": "Antivirus", "correct": false, "because": "Erkennt Malware"}, {"text": "Neuer Drucker", "correct": true, "because": "Kein Sicherheitsvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Cyberangriffe nur digital?', 2, '[{"text": "Nein", "correct": true, "because": "Auch physische Angriffe möglich"}, {"text": "Ja", "correct": false, "because": "Kombinationen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzmaßnahmen sind essenziell?', 4, '[{"text": "Schulungen", "correct": true, "because": "Reduziert Fehler"}, {"text": "Backups", "correct": true, "because": "Wiederherstellung möglich"}, {"text": "Schnellere CPUs", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass starke Passwörter ausreichen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "MFA nötig"}, {"text": "Ja", "correct": false, "because": "Nur ein Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verteidigung?', 3, '[{"text": "Nutzerbewusstsein", "correct": true, "because": "Häufigster Schwachpunkt"}, {"text": "Maximale Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Schnelle Installation", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Angriffe nutzen Bots. b) Sie sind nur lokal gefährlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Global möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Angriffsarten gibt es?', 5, '[{"text": "DDoS", "correct": true, "because": "Überlastet Systeme"}, {"text": "SQL-Injection", "correct": true, "because": "Manipuliert Datenbanken"}, {"text": "Hardware-Tuning", "correct": false, "because": "Kein Angriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abwehr unwichtig?', 3, '[{"text": "Patch-Management", "correct": false, "because": "Schließt Lücken"}, {"text": "Überwachung", "correct": false, "because": "Erkennt Angriffe"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind alle Angriffe laut?', 3, '[{"text": "Nein", "correct": true, "because": "Viele sind stealthy"}, {"text": "Ja", "correct": false, "because": "Nicht immer offensichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Cyberangriffe nur Firmen betreffen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Privatpersonen betroffen"}, {"text": "Ja", "correct": false, "because": "Breiteres Spektrum"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt KI bei Angriffen?', 4, '[{"text": "Automatisierung", "correct": true, "because": "Erhöht Effizienz"}, {"text": "Grafikverbesserung", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Nicht relevant"}]');
